package com.jinloes.practice;
import java.util.List; import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: semicolon-separated operations record <name> <time> and query <freq> <name> <start> <end>, for example: record a 0; record a 60; query minute a 0 60"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ",args).trim()); return;} Solution a=new Solution(); a.recordTweet("a",0); a.recordTweet("a",60); assertThat(a.getTweetCountsPerFrequency("minute","a",0,60)).as("Example 1").containsExactly(1,1); Solution b=new Solution(); b.recordTweet("a",10); b.recordTweet("a",70); assertThat(b.getTweetCountsPerFrequency("hour","a",0,3599)).as("Example 2").containsExactly(2); assertThat(new Solution().getTweetCountsPerFrequency("minute","missing",0,120)).as("Example 3").containsExactly(0,0,0); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ Solution c=new Solution(); List<Integer> last=null; for(String op:input.split(";")){ String[] p=op.trim().split("\s+"); if(p.length==3&&p[0].equals("record")) c.recordTweet(p[1],Integer.parseInt(p[2])); else if(p.length==5&&p[0].equals("query")) last=c.getTweetCountsPerFrequency(p[1],p[2],Integer.parseInt(p[3]),Integer.parseInt(p[4])); else throw new IllegalArgumentException(); } if(last==null) throw new IllegalArgumentException(); System.out.println("counts = "+last); }catch(RuntimeException e){ System.out.println("Could not read operations. "+USAGE); } } }
